CREATE COLUMN TABLE "TEST_AP"."OALR" ("Code" INTEGER CS_INT NOT NULL , "Type" NVARCHAR(1) DEFAULT 'A', "Priority" NVARCHAR(1) DEFAULT '1', "TCode" INTEGER CS_INT, "Subject" NVARCHAR(254), "UserText" NCLOB MEMORY THRESHOLD 1000, "DataCols" INTEGER CS_INT, "DataParams" NCLOB MEMORY THRESHOLD 1000, "MsgData" NCLOB MEMORY THRESHOLD 1000, "UserSign" SMALLINT CS_INT, "Attachment" NCLOB MEMORY THRESHOLD 1000, "DataSource" NVARCHAR(1) DEFAULT 'N', "AtcEntry" INTEGER CS_INT, "AltType" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OALR_USER" ON "TEST_AP"."OALR" ( "UserSign" ASC )